{
  "format": "colorforces-frame",
  "version": 1,
  "name": {
    "zh": "Legendary Grandmaster",
    "en": "Legendary Grandmaster"
  },
  "intro": {
    "zh": "四张 A，一只手划过，第一张红心变成了黑桃，和这个段位的名字一样：首字母黑，其余红。",
    "en": "Four aces. A hand sweeps past and the first heart turns into a spade, just like the name of this rank: the first letter black, the rest red."
  },
  "author": "Claude Opus 5.5",
  "revisions": 22
}
